# Writes the hedra command files of the bee garden's world and props: island.txt (lawn, patches,
# soil mounds under the flower slots), hive.txt, bush.txt, fence.txt, rock.txt, flower_pink.txt,
# flower_white.txt, wilt.txt, spider.txt, sparkle.txt. Run from models/env: /usr/bin/python3 make_env.py
# Up Z, front -Y (hedra); colours exact FunkyFuture 8. World (glTF) = (x, z, -y) of hedra.
import math, random

HEX = {"navy": "2b0f54", "plum": "ab1f65", "pink": "ff4f69", "white": "fff7f8",
       "orange": "ff8142", "yellow": "ffda45", "blue": "3368dc", "cyan": "49e7ec"}
def col(n, emit=False):
    h = HEX[n]; r, g, b = (int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
    s = f"--base-color {r:.4f} {g:.4f} {b:.4f}"
    return s + (f" --emission {r:.4f} {g:.4f} {b:.4f}" if emit else "")

R = 4.6
# flower slots, world x/z (the game reads the same list): hedra y = -z
SLOTS = [(0.0, 0.3), (2.4, 0.4), (1.3, 2.4), (-1.2, 2.5), (-2.5, 0.5), (-1.1, -1.7), (1.4, -1.6)]
HIVE = (-3.2, -2.5)

def circ(x, y, r):
    return f"((pos.x - ({x:.3f}))*(pos.x - ({x:.3f})) + (pos.y - ({y:.3f}))*(pos.y - ({y:.3f})) < {r*r:.4f})"

files = {}

# ---------------------------------------------------------------- island
rnd = random.Random(7)
patches = []
for i in range(30):
    a = rnd.uniform(0, 2 * math.pi); d = rnd.uniform(0.5, 4.1)
    x, y = d * math.cos(a), d * math.sin(a)
    patches.append(circ(x, y, rnd.uniform(0.16, 0.3)))
soil = " || ".join(circ(x, -z, 0.36) for x, z in SLOTS)
hivepad = circ(HIVE[0], -HIVE[1], 0.75)
files["island"] = f"""# Garden island: a 20-sided lawn slab (top at z 0) on an earth rim and a rocky underside cone.
# The top is fanned and subdivided so light-grass patches and soil mounds (under the seven flower
# slots and the hive) are picked as faces. Generated by make_env.py. Up Z, front -Y.
new
material new Lawn {col('blue')} --no-slot
material new Clover {col('cyan')} --no-slot
material new Soil {col('plum')} --no-slot
material new Earth {col('plum')} --no-slot
add mesh cylinder --name Island --vertices 20 --radius {R} --depth 0.5 --location 0 0 -0.25
apply --location
material assign Earth
mode edit
select face where "normal.z < -0.9"
delete only-faces
select face where "normal.z > 0.9"
poke
select face where "normal.z > 0.5"
subdivide --cuts 9
select face where "normal.z > 0.5"
material assign Lawn
select face where "normal.z > 0.5 && ({' || '.join(patches)})"
material assign Clover
select face where "normal.z > 0.5 && ({soil} || {hivepad})"
material assign Soil
translate 0 0 0.03
mode object
add mesh cone --name Under --vertices 10 --radius1 {R*0.97:.2f} --radius2 0.6 --depth 2.2 --location 0 0 -1.6 --rotation 180 0 0
apply --rotation
material assign Earth
mode edit
select face where "normal.z > 0.9"
delete only-faces
select vert where "pos.z < 0.9"
randomize --amount 0.18 --seed 5
mode object
select Island Under
active Island
join
shade flat
export island.glb
"""

# ---------------------------------------------------------------- hive (a skep on a stump)
rings = []
for i, (z, r) in enumerate([(0.62, 0.55), (0.82, 0.56), (1.02, 0.52), (1.2, 0.44), (1.36, 0.32), (1.48, 0.17)]):
    rings.append(f"add mesh cylinder --name Ring{i} --vertices 10 --radius {r} --depth 0.2 --location 0 0 {z}")
    rings.append("mode edit\nselect face where \"normal.z > 0.9\"\nscale 0.86 0.86 1\nmode object")
files["hive"] = f"""# Hive: a straw skep of six stacked, tapering rings on a low stump, a dark entrance at the front.
# Generated by make_env.py. Up Z, front -Y.
new
material new Straw {col('orange')} --no-slot
material new Wood {col('plum')} --no-slot
material new Hole {col('navy')} --no-slot
add mesh cylinder --name Stump --vertices 9 --radius 0.55 --depth 0.52 --location 0 0 0.26
material assign Wood
""" + "\n".join(rings) + f"""
select Ring0 Ring1 Ring2 Ring3 Ring4 Ring5
active Ring0
join
rename Ring0 Skep
material assign Straw
add mesh cube --name Hole --size 1 --location 0 -0.5 0.66
scale 0.26 0.14 0.18
apply --scale
material assign Hole
shade flat
select all
shade flat
export hive.glb
"""

# ---------------------------------------------------------------- bush
files["bush"] = f"""# Bush: three faceted lumps of cyan foliage. Generated by make_env.py. Up Z.
new
material new Leaf {col('cyan')} --no-slot
add mesh ico-sphere --name B0 --subdivisions 1 --radius 0.55 --location 0 0 0.42
add mesh ico-sphere --name B1 --subdivisions 1 --radius 0.42 --location 0.5 0.15 0.32
add mesh ico-sphere --name B2 --subdivisions 1 --radius 0.38 --location -0.45 0.1 0.3
select B0 B1 B2
active B0
join
rename B0 Bush
material assign Leaf
mode edit
select all
randomize --amount 0.05 --seed 2
mode object
shade flat
export bush.glb
"""

# ---------------------------------------------------------------- fence (an arc at the back rim)
pk = []
angs = [math.radians(a) for a in range(38, 143, 9)]
for i, a in enumerate(angs):
    x, y = (R - 0.25) * math.cos(a), (R - 0.25) * math.sin(a)
    pk.append(f"add mesh cube --name P{i} --size 1 --location {x:.3f} {y:.3f} 0.38")
    pk.append("scale 0.16 0.1 0.76\napply --scale")
    pk.append("mode edit\nselect vert where \"pos.z > 0.3\"\nscale 0.3 1 1\nmode object")
    pk.append(f"set rotation 0 0 {math.degrees(a) - 90:.2f}")
rails = []
for j, z in enumerate((0.25, 0.52)):
    for i in range(len(angs) - 1):
        a0, a1 = angs[i], angs[i + 1]
        am = (a0 + a1) / 2
        x, y = (R - 0.3) * math.cos(am), (R - 0.3) * math.sin(am)
        L = 2 * (R - 0.3) * math.sin((a1 - a0) / 2) + 0.06
        rails.append(f"add mesh cube --name Rl{j}_{i} --size 1 --location {x:.3f} {y:.3f} {z}")
        rails.append(f"scale {L:.3f} 0.07 0.1\napply --scale\nset rotation 0 0 {math.degrees(am) - 90:.2f}")
names = " ".join([f"P{i}" for i in range(len(angs))] + [f"Rl{j}_{i}" for j in range(2) for i in range(len(angs) - 1)])
files["fence"] = f"""# Fence: a picket arc along the back rim of the lawn (white pickets, pointed tops, two rails).
# Generated by make_env.py. Up Z, front -Y; built in place (the island's coordinates).
new
material new Picket {col('white')} --no-slot
""" + "\n".join(pk + rails) + f"""
select {names}
active P0
join
rename P0 Fence
material assign Picket
shade flat
export fence.glb
"""

# ---------------------------------------------------------------- rock
files["rock"] = f"""# Rock: a jittered icosahedron. Generated by make_env.py. Up Z.
new
material new Stone {col('plum')} --no-slot
add mesh ico-sphere --name Rock --subdivisions 1 --radius 0.35 --location 0 0 0.12
scale 1.3 1.0 0.7
apply --scale
material assign Stone
mode edit
select all
randomize --amount 0.06 --seed 3
mode object
shade flat
export rock.glb
"""

# ---------------------------------------------------------------- flowers
def flower(name, petal, centre, n=6):
    parts = [f"add mesh cylinder --name Centre --vertices 8 --radius 0.17 --depth 0.12 --location 0 0 0.02"]
    pn = []
    for i in range(n):
        a = 2 * math.pi * i / n + math.pi / 2
        x, y = 0.3 * math.cos(a), 0.3 * math.sin(a)
        parts.append(f"add mesh ico-sphere --name Pt{i} --subdivisions 1 --radius 0.2 --location {x:.3f} {y:.3f} 0")
        parts.append(f"scale 1.0 0.62 0.32\napply --scale\nset rotation 0 0 {math.degrees(a):.1f}\napply --rotation")
        pn.append(f"Pt{i}")
    return f"""# Flower ({name}): a cyan stem with two leaves, a head of {n} {name} petals round a gold centre,
# tilted 40 degrees towards the camera. Origin at the stem's foot. Generated by make_env.py. Up Z.
new
material new Petal {col(petal)} --no-slot
material new Centre {col(centre)} --no-slot
material new Stem {col('cyan')} --no-slot
""" + "\n".join(parts) + f"""
select {' '.join(pn)}
active Pt0
join
rename Pt0 Petals
material assign Petal
select Centre
material assign Centre
select Petals Centre
active Centre
join
rename Centre Head
set rotation 40 0 0
apply --rotation
set location 0 -0.08 0.95
apply --location
add mesh cylinder --name Stalk --vertices 6 --radius 0.07 --depth 0.95 --location 0 0 0.47
add mesh cube --name LeafL --size 1 --location -0.2 0 0.35
scale 0.36 0.16 0.07
apply --scale
set rotation 0 -30 0
add mesh cube --name LeafR --size 1 --location 0.2 0 0.5
scale 0.36 0.16 0.07
apply --scale
set rotation 0 30 0
select Stalk LeafL LeafR
active Stalk
join
rename Stalk Stem
material assign Stem
select Head Stem
active Stem
join
rename Stem Flower
shade flat
export flower_{name}.glb
"""
files["flower_pink"] = flower("pink", "pink", "yellow")
files["flower_white"] = flower("white", "white", "yellow", 8)

# wilted: the stem bends over, the head hangs, dark petals
wp = ["add mesh cylinder --name Centre --vertices 8 --radius 0.15 --depth 0.1 --location 0 0 0"]
for i in range(5):
    a = 2 * math.pi * i / 5 + math.pi / 2
    x, y = 0.26 * math.cos(a), 0.26 * math.sin(a)
    wp.append(f"add mesh ico-sphere --name Pt{i} --subdivisions 1 --radius 0.18 --location {x:.3f} {y:.3f} -0.05")
    wp.append(f"scale 1.0 0.6 0.3\napply --scale\nset rotation 0 0 {math.degrees(a):.1f}\napply --rotation")
files["wilt"] = f"""# Wilted flower: the stem bends over at mid height, the dark head hangs face down towards the front.
# Origin at the stem's foot. Generated by make_env.py. Up Z.
new
material new Petal {col('plum')} --no-slot
material new Centre {col('orange')} --no-slot
material new Stem {col('blue')} --no-slot
""" + "\n".join(wp) + f"""
select Pt0 Pt1 Pt2 Pt3 Pt4
active Pt0
join
rename Pt0 Petals
material assign Petal
select Centre
material assign Centre
select Petals Centre
active Centre
join
rename Centre Head
set rotation 130 0 0
apply --rotation
set location 0 -0.42 0.48
apply --location
add mesh cylinder --name Low --vertices 6 --radius 0.07 --depth 0.5 --location 0 0 0.25
add mesh cylinder --name Up --vertices 6 --radius 0.065 --depth 0.42 --location 0 -0.16 0.62 --rotation -60 0 0
apply --rotation
add mesh cube --name Leaf --size 1 --location 0.18 0 0.18
scale 0.32 0.14 0.07
apply --scale
set rotation 0 50 0
select Low Up Leaf
active Low
join
rename Low Stem
material assign Stem
select Head Stem
active Stem
join
rename Stem Wilt
shade flat
export wilt.glb
"""

# ---------------------------------------------------------------- spider
legs = []
ln = []
for side in (-1, 1):
    for k, ang in enumerate((-50, -18, 18, 50)):
        a = math.radians(ang)
        # upper segment rises outwards, lower segment drops to the ground
        ux, uy = side * 0.36 * math.cos(a), 0.36 * math.sin(a) * 1.0
        legs.append(f"add mesh cube --name U{side+1}{k} --size 1 --location {side*0.2 + ux*0.5:.3f} {uy*0.5 - 0.02:.3f} 0.36")
        legs.append(f"scale 0.4 0.1 0.1\napply --scale\nset rotation 0 {-side*25} {ang*side:.1f}\napply --rotation")
        lx, ly = side * (0.2 + 0.36 * math.cos(a)) , 0.36 * math.sin(a) - 0.02
        legs.append(f"add mesh cube --name L{side+1}{k} --size 1 --location {lx + side*0.08*math.cos(a):.3f} {ly + 0.08*math.sin(a):.3f} 0.2")
        legs.append(f"scale 0.1 0.1 0.38\napply --scale\nset rotation 0 {side*20} {ang*side:.1f}\napply --rotation")
        ln += [f"U{side+1}{k}", f"L{side+1}{k}"]
files["spider"] = f"""# Spider: a round abdomen, a smaller head with two pink eyes at the front, eight bent legs
# (each two boxes, 0.1 m thick). Origin on the ground under the body. Generated by make_env.py. Up Z.
new
material new Body {col('navy')} --no-slot
material new Eye {col('pink')} --no-slot
add mesh ico-sphere --name Abdomen --subdivisions 1 --radius 0.3 --location 0 0.18 0.42
scale 1.0 1.15 0.85
apply --scale
add mesh ico-sphere --name Head --subdivisions 1 --radius 0.18 --location 0 -0.22 0.36
""" + "\n".join(legs) + f"""
select Abdomen Head {' '.join(ln)}
active Abdomen
join
rename Abdomen Spider
material assign Body
add mesh cube --name EyeL --size 1 --location -0.08 -0.38 0.42
scale 0.09 0.06 0.09
apply --scale
add mesh cube --name EyeR --size 1 --location 0.08 -0.38 0.42
scale 0.09 0.06 0.09
apply --scale
select EyeL EyeR
active EyeL
join
rename EyeL Eyes
material assign Eye
select all
shade flat
export spider.glb
"""

# ---------------------------------------------------------------- sparkle
files["sparkle"] = f"""# Sparkle: a small glowing octahedron (pollen burst), origin at its centre. Generated by make_env.py.
new
material new Pollen {col('yellow', True)} --no-slot
add mesh ico-sphere --name Sparkle --subdivisions 1 --radius 0.1 --location 0 0 0
material assign Pollen
shade flat
export sparkle.glb
"""

for k, v in files.items():
    open(f"{k}.txt", "w").write(v)
print("wrote", ", ".join(f"{k}.txt" for k in files))
